import "dart:io"; void main() { var f = File("lib/screens/radio/data/recitation_categories_data.dart"); var lines = f.readAsLinesSync(); var out = <String>[]; bool skip = false; for (var l in lines) { if (l.contains("static List<RecitationCategory> build() {")) { skip = true; out.add("  static List<RecitationCategory> build() {"); out.add("    if (_liveList.isEmpty) { return [_buildRecitersCategory()]; }"); out.add("    return List.unmodifiable(_liveList);"); out.add("  }"); out.add(""); out.add("  static Future<void> initialize({bool refreshRemote = false}) async {"); out.add("    if (_initialized && !refreshRemote) return;"); out.add("    if (_initializing) { await _initCompleter?.future; return; }"); out.add("    _initializing = true; _initCompleter = Completer<void>();"); out.add("    _addCategory(_buildRecitersCategory());"); out.add("    try {"); out.add("      await _loadCachedCategoriesStreaming();"); out.add("      await _loadLocalAssetsStreaming();"); out.add("      await _loadCachedYouTubeCategories();"); out.add("      _initialized = true;"); out.add("      _runBackgroundSync(refreshRemote);"); out.add("    } finally {"); out.add("      _initializing = false; if (!_initCompleter!.isCompleted) _initCompleter!.complete();"); out.add("    }"); out.add("    debugPrint('✅ Total (Local): \\${_liveList.length} categories');"); out.add("  }"); out.add(""); out.add("  static Future<void> _runBackgroundSync(bool refreshRemote) async {"); out.add("    try {"); out.add("      final now = DateTime.now();"); out.add("      final shouldSync = refreshRemote || _lastRemoteSync == null || now.difference(_lastRemoteSync!) > _remoteCooldown;"); out.add("      if (shouldSync) { _lastRemoteSync = now; await _syncWithRemoteStreaming(); }"); out.add("      final shouldSyncYouTube = refreshRemote || _lastYouTubeSync == null || now.difference(_lastYouTubeSync!) > _youTubeCooldown;"); out.add("      if (shouldSyncYouTube) { _lastYouTubeSync = now; await _fetchYouTubeChannels(); }"); out.add("    } catch (e) { debugPrint('❌ Background sync error: \\$e'); }"); out.add("  }"); continue; } if (skip && l.contains("debugPrint('✅ Total: \\${_liveList.length} categories');")) { skip = false; continue; } if (skip && l.trim() == "}") { if (lines.indexOf(l) > 100 && lines.indexOf(l) < 115) { skip = false; continue; } } if (!skip) { out.add(l); } } f.writeAsStringSync(out.join("\n")); }
